import numpy as np
def equation(t, P, params):
    a,b,w,d,e,k = params[0],params[1],params[2],params[3],params[4],params[5]
    return a*t + b*np.sin(w*t)*(1/P) + d*(P*np.log(P)) + e*(t**k)*(1/P)

import numpy as np
def equation(t, P, params):
